import { z } from "zod";
import { Id, IsoDateTime } from "./common";

/** Hardware and software facts the player reports when pairing. */
export const DeviceInfo = z.object({
  /** Random UUID generated by the app on first launch and kept for its lifetime. */
  hardwareId: z.string().min(8).max(128),
  manufacturer: z.string().max(100),
  model: z.string().max(100),
  androidVersion: z.string().max(20),
  sdkInt: z.number().int().min(1),
  appVersionName: z.string().max(50),
  appVersionCode: z.number().int().min(0),
  screenWidth: z.number().int().min(0),
  screenHeight: z.number().int().min(0),
  freeStorageBytes: z.number().int().min(0),
  totalStorageBytes: z.number().int().min(0),
  /** MIME types the device can decode in hardware or software, e.g. "video/avc". */
  videoDecoders: z.array(z.string().max(100)).max(200),
});
export type DeviceInfo = z.infer<typeof DeviceInfo>;

/** POST {DEVICE_API_BASE}/pair */
export const PairRequest = z.object({
  device: DeviceInfo,
});
export type PairRequest = z.infer<typeof PairRequest>;

export const PairResponse = z.object({
  /** Six digits, shown large on the TV and typed into the panel. */
  pairingCode: z.string().regex(/^\d{6}$/),
  /** Secret only the device knows; used to poll for the result. */
  pairingSecret: z.string().min(32).max(128),
  expiresAt: IsoDateTime,
  pollIntervalSec: z.number().int().min(1),
});
export type PairResponse = z.infer<typeof PairResponse>;

/** POST {DEVICE_API_BASE}/pair/poll */
export const PairPollRequest = z.object({
  pairingSecret: z.string().min(32).max(128),
});
export type PairPollRequest = z.infer<typeof PairPollRequest>;

export const PairPollResponse = z.discriminatedUnion("status", [
  z.object({ status: z.literal("pending") }),
  z.object({
    status: z.literal("paired"),
    deviceId: Id,
    /** Long-lived bearer token. Delivered exactly once. */
    deviceToken: z.string().min(32).max(256),
    deviceName: z.string(),
  }),
  z.object({ status: z.literal("expired") }),
]);
export type PairPollResponse = z.infer<typeof PairPollResponse>;

export const SyncState = z.enum(["idle", "downloading", "error"]);
export type SyncState = z.infer<typeof SyncState>;

/** Periodic report from the device (WebSocket "status" message or POST {DEVICE_API_BASE}/status). */
export const DeviceStatus = z.object({
  /** Manifest version currently applied on the device, null before the first sync. */
  manifestVersion: z.number().int().nullable(),
  activePlaylistId: Id.nullable(),
  currentMediaId: Id.nullable(),
  syncState: SyncState,
  syncFilesDone: z.number().int().min(0),
  syncFilesTotal: z.number().int().min(0),
  syncBytesDone: z.number().int().min(0),
  syncBytesTotal: z.number().int().min(0),
  lastError: z.string().max(1000).nullable(),
  freeStorageBytes: z.number().int().min(0),
  uptimeSec: z.number().int().min(0),
  appVersionName: z.string().max(50),
  appVersionCode: z.number().int().min(0),
  /** Current media volume 0-100, null if unknown. */
  volume: z.number().int().min(0).max(100).nullable(),
  /** "Display over other apps" permission granted (needed to come to front on wake). */
  overlayPermission: z.boolean(),
  /** App is provisioned as Device Owner (launcher lock, silent updates, reboot). */
  deviceOwner: z.boolean(),
});
export type DeviceStatus = z.infer<typeof DeviceStatus>;

/** Response to POST {DEVICE_API_BASE}/status */
export const StatusAck = z.object({
  /** Latest manifest version on the server; the device fetches the manifest if it differs. */
  manifestVersion: z.number().int().min(1),
});
export type StatusAck = z.infer<typeof StatusAck>;

/** POST {DEVICE_API_BASE}/commands/:id/result */
export const CommandResult = z.object({
  ok: z.boolean(),
  message: z.string().max(1000).nullable(),
});
export type CommandResult = z.infer<typeof CommandResult>;
